"""Idiomas de la interfaz PySide6 de AMPERA (20 idiomas más hablados).

El español es el idioma base: si una clave falta en el idioma activo se usa la
versión española, y si tampoco existe se devuelve la propia clave. Así una
traducción incompleta nunca rompe la ventana.

El idioma elegido se guarda en `config.json` con la misma clave que usa la
interfaz clásica (`idioma`), para que ambas recuerden la misma elección.
"""

from __future__ import annotations

from datos import dic, escribir, leer
from rutas import data_path

CONFIG = data_path("config.json")

