for _clave, _valores in _EXTRA.items():
    for _codigo, _texto in _valores.items():
        CATALOGO[_codigo][_clave] = _texto

_actual = "es"

# Idioma de Windows -> código del pack. Lo que no esté aquí cae en español.
_LCID = {
    0x0409: "en", 0x0809: "en", 0x0C09: "en", 0x1009: "en",
    0x0804: "zh", 0x1004: "zh", 0x0404: "zh", 0x0C04: "zh", 0x1404: "zh",
    0x0439: "hi", 0x040A: "es", 0x080A: "es", 0x0C0A: "es", 0x2C0A: "es",
    0x040C: "fr", 0x080C: "fr", 0x0C0C: "fr", 0x100C: "fr",
    0x0401: "ar", 0x0801: "ar", 0x2C01: "ar",
    0x0845: "bn", 0x0445: "bn",
    0x0416: "pt", 0x0816: "pt",
    0x0419: "ru",
    0x0420: "ur", 0x0820: "ur",
    0x0421: "id",
    0x0407: "de", 0x0807: "de", 0x0C07: "de",
    0x0411: "ja",
    0x0449: "mr", 0x044A: "te", 0x041F: "tr", 0x044B: "ta",
    0x042A: "vi",
}


def codigos() -> list[str]:
    return [c for c, _ in IDIOMAS]


def nombre(codigo: str) -> str:
    for c, n in IDIOMAS:
        if c == codigo:
            return n
    return codigo


def idioma_actual() -> str:
    return _actual


def rtl(codigo: str | None = None) -> bool:
    return (codigo or _actual) in ("ar", "ur")


def usar(codigo: str) -> str:
    global _actual
    if codigo in CATALOGO:
        _actual = codigo
    return _actual


def t(clave: str, **fmt) -> str:
    """Traduce `clave`; sin traducción cae al inglés, al español y a la clave."""
    texto = CATALOGO.get(_actual, {}).get(clave)
    if texto is None:
        texto = CATALOGO.get("en", {}).get(clave)
    if texto is None:
        texto = BASE.get(clave, clave)
    if fmt:
        try:
            texto = texto.format(**fmt)
        except Exception:
            pass
    return texto


# Planes de energia de Windows: alias del backend -> clave traducida.
PLANES_WINDOWS = {
    "alto": "plan_alto",
    "maximo": "plan_maximo",
    "equilibrado": "plan_equilibrado",
    "bajo": "plan_bajo",
}

# Clave del perfil de fabrica. "aaa_max" es la clave antigua que quedo en los
# perfiles ya guardados: solo se trata como fabrica si nadie la toco (nota vacia
# o la de antes); si el usuario la personalizo, manda su nombre y su nota.
PERFIL_FABRICA = "fabrica"
PERFIL_FABRICA_ANTIGUO = "aaa_max"
NOTA_FABRICA_ANTIGUA = "Perfil de fabrica: todo el poder disponible."


def nombre_plan(alias: str | None, texto: str) -> str:
    """Nombre del plan en el idioma de la app si es uno de los de Windows."""
    clave = PLANES_WINDOWS.get(str(alias or ""))
    return t(clave) if clave else str(texto or "")


def _fabrica_intacto(clave: str, nota: str) -> bool:
    """El perfil de fabrica, o el viejo sin personalizar."""
    if str(clave or "") == PERFIL_FABRICA:
        return True
    return (str(clave or "") == PERFIL_FABRICA_ANTIGUO
            and str(nota or "").strip() in ("", NOTA_FABRICA_ANTIGUA))


def es_perfil_fabrica(clave: str) -> bool:
    """True solo para el perfil que crea la app; los viejos se miran con su nota."""
    return str(clave or "") == PERFIL_FABRICA


def nombre_perfil(clave: str, nota: str | None = None) -> str:
    """Nombre visible del perfil: el de fabrica se traduce."""
    if _fabrica_intacto(clave, nota or ""):
        return t("perfil_fabrica")
    return str(clave or "")


def nota_perfil(clave: str, nota: str | None = None) -> str:
    """Nota visible: la del perfil de fabrica se escribe en el idioma elegido."""
    texto = str(nota or "").strip()
    if _fabrica_intacto(clave, texto) and texto in ("", NOTA_FABRICA_ANTIGUA):
        return t("perfil_fabrica_nota")
    return texto


def _idioma_sistema() -> str | None:
    try:
        import ctypes
        return _LCID.get(ctypes.windll.kernel32.GetUserDefaultUILanguage())
    except Exception:
        return None


def leer_config() -> dict:
    crudo, _ = leer(CONFIG, {})
    return dic(crudo)


def guardar(codigo: str) -> None:
    cfg = leer_config()
    cfg["idioma"] = codigo
    try:
        escribir(CONFIG, cfg)
    except Exception:
        pass


def iniciar() -> str:
    """Idioma guardado > idioma de Windows > español."""
    codigo = leer_config().get("idioma")
    if codigo not in CATALOGO:
        codigo = _idioma_sistema() or "es"
    return usar(codigo)

